"use strict";
/* =========================================================
   A-HLR SIMULATOR, ERC 2025
   ========================================================= */
const $=id=>document.getElementById(id);
const rnd=(a,b)=>a+Math.random()*(b-a);
const chance=p=>Math.random()<p;
/* Riskroll: används ENDAST för saker som kan gå FEL. noFail nollar dessa,
   till skillnad från chance() som också avgör lyckade utfall (ROSC, intubation). */
const risk=p=>(typeof DBG!=="undefined"&&DBG.on&&DBG.noFail)?false:Math.random()<p;
/* Framgångsroll: noFail garanterar att den lyckas. */
const succeed=p=>(typeof DBG!=="undefined"&&DBG.on&&DBG.noFail)?true:Math.random()<p;
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));

/* ---------- DEBUG (endast utveckling) ----------
   Fyra oberoende reglage. Håll dem separata: "instant" döljer kö- och
   eskaleringssystemet, vilket är just det man ofta vill testa. */
const DBG={ on:false, unlock:false, instant:false, noFail:false, freeROSC:false };
function dbgActive(){ return DBG.on&&(DBG.unlock||DBG.instant||DBG.noFail||DBG.freeROSC); }
const mmss=t=>{t=Math.max(0,Math.floor(t));return String(Math.floor(t/60)).padStart(2,"0")+":"+String(t%60).padStart(2,"0")};

